import React, { createContext, useContext, useState } from 'react';

const AudioContext = createContext();

export const AudioProvider = ({ children }) => {
  const [audioDetails, setAudioDetails] = useState(null);

  // Play a chapter
  const playChapter = ({ audioUrl, chapterTitle, book }) => {
    setAudioDetails({ audioUrl, chapterTitle, book });
  };

  // Stop or close the player
  const stopChapter = () => setAudioDetails(null);

  return (
    <AudioContext.Provider value={{ audioDetails, playChapter, stopChapter }}>
      {children}
    </AudioContext.Provider>
  );
};

// Hook to use in any component
export const useAudio = () => useContext(AudioContext);
